export function t(lang, key, vars) {
  let str = (STRINGS[lang] && STRINGS[lang][key]) || STRINGS.swe[key] || key;
  if (vars) Object.entries(vars).forEach(([k, v]) => { str = str.split(`{${k}}`).join(v); });
  return str;
}
